"""Independent reference: runs compilation, changes, brute-force optima."""
import itertools

U = 1 << 128

def compile_runs(routes):
    """routes: dict (addr, length) -> hop. Returns [(start, hop)] coalesced."""
    events = []
    for (s, ln), hop in routes.items():
        events.append((s, 1, ln, hop))
        end = s + (1 << (128 - ln))
        if end < U:
            events.append((end, -1, ln, hop))
    events.sort()
    active = {}
    hops_of = {}
    runs = []
    prev = 0

    def top():
        for ln in sorted(active, reverse=True):
            if active[ln]:
                return ln
        return None

    k = 0
    while k < len(events):
        p = events[k][0]
        t = top()
        hop = hops_of.get(t) if t is not None else None
        if prev < p and (not runs or runs[-1][1] != hop):
            runs.append((prev, hop))
        while k < len(events) and events[k][0] == p:
            pos, d, ln, hop = events[k]
            if d > 0:
                active[ln] = active.get(ln, 0) + 1
                hops_of[ln] = hop
            else:
                active[ln] -= 1
            k += 1
        prev = p
    t = top()
    hop = hops_of.get(t) if t is not None else None
    if not runs or runs[-1][1] != hop:
        runs.append((prev, hop))
    return runs


def changes(runs_a, runs_b):
    out = []
    ia = ib = 0
    pos = 0
    while True:
        na = runs_a[ia + 1][0] if ia + 1 < len(runs_a) else U
        nb = runs_b[ib + 1][0] if ib + 1 < len(runs_b) else U
        end = min(na, nb)
        o, n = runs_a[ia][1], runs_b[ib][1]
        if o != n:
            if out and out[-1][2] == o and out[-1][3] == n and out[-1][1] == pos:
                out[-1] = (out[-1][0], end, o, n)
            else:
                out.append((pos, end, o, n))
        if end == U:
            break
        if end == na:
            ia += 1
        if end == nb:
            ib += 1
        pos = end
    return out


WIDTH = (16, 8, 4)
LANES = (4, 8, 16)


def q_t(starts, bursts):
    R = len(starts)
    Q = [[0] * (R + 1) for _ in range(R + 1)]
    T = [[0] * (R + 1) for _ in range(R + 1)]
    for rep, cnt in bursts:
        for i in range(R):
            acc = 0
            for j in range(i + 1, R + 1):
                acc += cnt[j - 1]
                Q[i][j] += rep * acc
                if acc:
                    T[i][j] += rep
    return Q, T


class TooBig(Exception):
    pass


def _common(starts, bursts, C, hit, miss, dec):
    R = len(starts)
    Q, T = q_t(starts, bursts)

    def legal(i, j, mode):
        if mode == 0:
            return True
        spread = starts[j - 1] - starts[i]
        return spread < (1 << (64 if mode == 1 else 32))

    return R, Q, T, legal


def brute_full(starts, bursts, C, hit, miss, dec, limit=300000):
    """Truly exhaustive enumeration of every legal tree/mode/caching choice.
    Only usable for tiny R.  Returns dict resident -> lex-min (work,pages)."""
    R, Q, T, legal = _common(starts, bursts, C, hit, miss, dec)
    budget = [limit]

    def gen(i, j):
        L = j - i
        out = []
        if L <= 8:
            for mode in range(3):
                if not legal(i, j, mode):
                    continue
                used = 32 + L * WIDTH[mode]
                P = (used + 63) // 64
                kc = (L + LANES[mode] - 1) // LANES[mode] + dec[mode]
                for cached in (0, 1):
                    budget[0] -= 1
                    if budget[0] < 0:
                        raise TooBig
                    work = P * (hit if cached else miss) * T[i][j] + kc * Q[i][j]
                    out.append((work, P, cached * P))
        if L >= 2:
            for b in range(2, min(9, L) + 1):
                for cuts in itertools.combinations(range(1, L), b - 1):
                    bounds = (i,) + tuple(i + c for c in cuts) + (j,)
                    subs = [gen(bounds[t], bounds[t + 1]) for t in range(b)]
                    for mode in range(3):
                        if not legal(i, j, mode):
                            continue
                        used = 32 + 4 * b + (b - 1) * WIDTH[mode]
                        P = (used + 63) // 64
                        kc = ((b - 1) + LANES[mode] - 1) // LANES[mode] + dec[mode]
                        for cached in (0, 1):
                            base = P * (hit if cached else miss) * T[i][j] + kc * Q[i][j]
                            for combo in itertools.product(*subs):
                                budget[0] -= 1
                                if budget[0] < 0:
                                    raise TooBig
                                out.append((base + sum(c[0] for c in combo),
                                            P + sum(c[1] for c in combo),
                                            cached * P + sum(c[2] for c in combo)))
        return out

    byres = {}
    for w, p, r in gen(0, R):
        if r > C:
            continue
        if r not in byres or (w, p) < byres[r]:
            byres[r] = (w, p)
    return byres


def brute_pruned(starts, bursts, C, hit, miss, dec):
    """Top-down composition enumeration with per-resident lex-min pruning at
    each subrange (independent structure from the engine's bottom-up DP)."""
    R, Q, T, legal = _common(starts, bursts, C, hit, miss, dec)
    memo = {}

    def gen(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        L = j - i
        best = {}
        def offer(w, p, r):
            if r > C:
                return
            if r not in best or (w, p) < best[r]:
                best[r] = (w, p)
        if L <= 8:
            for mode in range(3):
                if not legal(i, j, mode):
                    continue
                used = 32 + L * WIDTH[mode]
                P = (used + 63) // 64
                kc = (L + LANES[mode] - 1) // LANES[mode] + dec[mode]
                for cached in (0, 1):
                    work = P * (hit if cached else miss) * T[i][j] + kc * Q[i][j]
                    offer(work, P, cached * P)
        if L >= 2:
            for b in range(2, min(9, L) + 1):
                for cuts in itertools.combinations(range(1, L), b - 1):
                    bounds = (i,) + tuple(i + c for c in cuts) + (j,)
                    subs = [gen(bounds[t], bounds[t + 1]) for t in range(b)]
                    # combine children resident splits exactly
                    combos = [(0, 0, 0)]
                    for s in subs:
                        nxt = []
                        for (w0, p0, r0) in combos:
                            for (w1, p1, r1) in s.items():
                                if r0 + r1 <= C:
                                    nxt.append((w0 + w1, p0 + p1, r0 + r1))
                        # prune per resident within the partial combination
                        tmp = {}
                        for (w0, p0, r0) in nxt:
                            if r0 not in tmp or (w0, p0) < tmp[r0]:
                                tmp[r0] = (w0, p0)
                        combos = [(w, p, r) for r, (w, p) in tmp.items()]
                    for mode in range(3):
                        if not legal(i, j, mode):
                            continue
                        used = 32 + 4 * b + (b - 1) * WIDTH[mode]
                        P = (used + 63) // 64
                        kc = ((b - 1) + LANES[mode] - 1) // LANES[mode] + dec[mode]
                        for cached in (0, 1):
                            base = P * (hit if cached else miss) * T[i][j] + kc * Q[i][j]
                            for (w, p, r) in combos:
                                offer(base + w, P + p, cached * P + r)
        memo[key] = best
        return best

    return gen(0, R)


def combine(per_byres, C, per_opts=None):
    """Combine per-version byres dicts under a shared budget.
    With per_opts (full option lists) a full product is used when feasible."""
    best = None
    if per_opts is not None:
        lists = [[o for o in opts if o[2] <= C] for opts in per_opts]
        total = 1
        for l in lists:
            total *= max(1, len(l))
        if total <= 20000000 and len(lists) <= 3:
            for combo in itertools.product(*lists):
                res = sum(c[2] for c in combo)
                if res > C:
                    continue
                w = sum(c[0] for c in combo)
                p = sum(c[1] for c in combo)
                if best is None or (w, p) < best:
                    best = (w, p)
            return best
    keys = [sorted(d) for d in per_byres]
    for combo in itertools.product(*keys):
        if sum(combo) > C:
            continue
        w = sum(per_byres[t][combo[t]][0] for t in range(len(per_byres)))
        p = sum(per_byres[t][combo[t]][1] for t in range(len(per_byres)))
        if best is None or (w, p) < best:
            best = (w, p)
    return best
